import { test, expect } from '@playwright/test';

test.describe('Phone Number Field Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/form'); // Replace with the actual URL of the form
  });

  test('should accept numeric input', async ({ page }) => {
    const phoneInput = page.getByLabel('Phone Number'); // Replace with the actual label of the phone number field
    await phoneInput.fill('1234567890');
    await expect(phoneInput).toHaveValue('1234567890');
  });

  test('should not accept non-numeric input', async ({ page }) => {
    const phoneInput = page.getByLabel('Phone Number'); // Replace with the actual label of the phone number field
    await phoneInput.fill('abc123');
    await expect(phoneInput).toHaveValue(''); // Assuming the field clears on invalid input
    await expect(phoneInput).toHaveAttribute('aria-invalid', 'true'); // Assuming aria-invalid is set for invalid input
  });
});
